import React, { useState, useEffect } from 'react';    // 1
import Login from './components/Login';                // 2
import Chat from './components/Chat';                  // 3

export default function App() {                       // 4
  const [user, setUser] = useState(null);             // 5

  // on mount, check if token+username exist
  useEffect(() => {                                   // 6
    const token = localStorage.getItem('token');     // 7
    const username = localStorage.getItem('username'); // 8
    if (token && username) setUser({ username });    // 9
  }, []);                                             // 10

  // handle logout
  const logout = () => {                              // 11
    localStorage.removeItem('token');                // 12
    localStorage.removeItem('username');             // 13
    setUser(null);                                   // 14
  };

  return (                                           // 15
    <div style={{ padding: 20, fontFamily: 'Arial' }}> 
      {!user ? (                                     // 16
        <Login onLogin={(u) => setUser(u)} />        // 17
      ) : (                                          // 18
        <Chat user={user} onLogout={logout} />       // 19
      )}
    </div>
  );                                                  // 20
}
